-- ---- M12003-01 (694a33e0) Anwendungsbereich und Wasserquelle — 7 field(s) ----
-- wasserquelle_typ
update public.fields set verification_status='verified_against_standard', verification_quote='Dieses Merkblatt gilt für die Wiederverwendung aufbereiteten Wassers aus kommunalen Kläranlagen mit überwiegendem Anteil häuslichen Schmutzwassers für landwirtschaftliche, gartenbauliche und urbane Anwendungen. | Nicht betrachtet wird die Wiederverwendung industrieller und gewerblicher Abwässer, zum Beispiel im Zuge der industriellen Kreislaufführung. — printed p.10', verification_note='md-verified 2026-09-05 (§1, printed p.10) [VC] — enum token hybrid carries regulation_reference §5.1.5 (a Wasserherkunft, not a §1 source type) — STAGED S-1', verified_at=now() where id='ce2146bd-452f-4b9e-8850-5242f56021c6' and verification_status not in ('verified_against_standard','corrected');
-- gueteklasse
update public.fields set verification_status='verified_against_standard', verification_quote='Die Zusammenführung ist in Tabelle 10 erfolgt, in der die Güteklassen von aufbereitetem Wasser den Bewässerungsverfahren sowie den zulässigen Verwendungszwecken zugeordnet werden (siehe Merkblatt DWA-M 1200-1:2025 in Abschnitt 5). | Tabelle 10: Anwendungsbereiche der Wasserwiederverwendung in Deutschland in Bezug zu den Güteklassen nach EU-WasserWVVO und weitere Spezifizierungen unter Berücksichtigung von DIN 19650:1999, ISO 16075-2:2020 sowie EU-Leitlinien 2022/C 298/01 und DIN 18035-2:2020 — printed p.38–39', verification_note='md-verified 2026-09-05 (§5.6.1 / Tab. 10, printed p.38–39) [VC] — the six enum tokens A, B-1, B-2, C-1, C-2, D are the row keys of Tab. 10 (md 1214/1226/1247/1256/1285/1295); the microbiological definition of each class is EU 2020/741 Anhang I (NR in this md)', verified_at=now() where id='1a7b2d89-aa44-4e6c-9c65-b70421f5f48a' and verification_status not in ('verified_against_standard','corrected');
-- anwendungsbereich
update public.fields set verification_status='verified_against_standard', verification_quote='Aufbereitetes Wasser als Bewässerungswasser kann, falls möglich und machbar, in folgenden Bereichen zur Anwendung kommen, sofern Bewässerungsbedürftigkeit bzw. -würdigkeit besteht: | Bewässerung in der Landwirtschaft: | Bewässerung im Gartenbau: [...] bei der Frostschutzberegnung; | Bewässerung für urbane Zwecke/Garten- und Landschaftsbau (GaLaBau): | sonstige Bewässerungszwecke [...] bewachsene Bereiche in Gleisanlagen. — printed p.13', verification_note='md-verified 2026-09-05 (§3, printed p.13) [VC] — tokens frostschutzberegnung (§3 Gartenbau bullet + §5.6.5) and gleisanlage (§3 sonstige + §5.5.5) are sub-items of the four printed headings; partition is EKOWAI''s', verified_at=now() where id='440c56a8-51f1-4f32-8b88-bf27a4c09fc5' and verification_status not in ('verified_against_standard','corrected');
-- wasserherkunft
update public.fields set verification_status='verified_against_standard', verification_quote='Bei Bewässerungssystemen und Bewässerungsnetzen mit hybriden Wasserherkünften ist ein Rückfluss von aufbereitetem Wasser in andere Quellen, wie Brunnen oder Leitungen, durch geeignete Maßnahmen und technische Vorkehrungen zu verhindern. | Hybride Wasserherkunft | Wasserherkunft aus verschiedenen Quellen — printed p.24 / p.11', verification_note='md-verified 2026-09-05 (§5.1.5; §2.1, printed p.24 / p.11) [VC]', verified_at=now() where id='331d706f-c187-43d2-b875-70429a89f7e1' and verification_status not in ('verified_against_standard','corrected');
-- alle_hygieneanforderungen_erfuellt
update public.fields set verification_status='verified_against_standard', verification_quote='Bei dem Einsatz von aufbereitetem Wasser ist sicherzustellen, dass die verwendete Wasserqualität entsprechend der Genehmigung eingehalten wird. Bei der Verwendung von Speichern oder ähnlichen Systemen, auch zum Transport von Wasser, ist dies zu berücksichtigen. — printed p.48', verification_note='md-verified 2026-09-05 (§7.1, printed p.48) [VC] — roll-up attestation flag; the obligation is printed', verified_at=now() where id='fbc058b3-a5b9-4d0e-b5e1-4ec36d2f233f' and verification_status not in ('verified_against_standard','corrected');
-- filter_und_desinfektion_gemaess_gueteklasse
update public.fields set verification_status='verified_against_standard', verification_quote='In Abhängigkeit von der Güteklasse und den bewässerten Kulturen können zur Gewährleistung der Funktionsfähigkeit, aber auch des Gesundheitsschutzes folgende zusätzliche Maßnahmen in Anlehnung an ISO 16075-3 angewendet werden, falls diese zweckdienlich sind: | Güteklasse A | Verwendung eines automatischen Scheibenfilters $(180 \mu \mathrm{~m})$ vor der Einspeisung in das Verteilungsnetz (in Abhängigkeit von der Partikelanzahl/-größe des bereitgestellten Wassers); | Spülung und Hygienisierung (Reinigung und Desinfektion) des Systems vor Beginn und nach Ende der Bewässerungssaison. — printed p.54', verification_note='md-verified 2026-09-05 (§7.3.2, printed p.54) [VC] — "können … falls zweckdienlich" — optional measures; CR-12 warn is the right severity', verified_at=now() where id='e52b57d3-3f76-4fff-b095-e872aadc60f0' and verification_status not in ('verified_against_standard','corrected');
-- beide_punkte_dokumentiert
update public.fields set verification_status='verified_against_standard', verification_quote='Im RMP sind die gegebenenfalls erforderlichen Abstände fallspezifisch aufzuführen. Sie sind Teil des Multibarrierenprinzips und dienen als eine der Grundlagen der Erlaubnis der Bewässerung mit aufbereitetem Wasser. | Die Kennzeichnung von Leitungen, Speichern sowie Verteilungs- und Aufbringungstechnik muss im RMP als solches konkretisiert und berücksichtigt werden (siehe auch Abschnitt 6). — printed p.23', verification_note='md-verified 2026-09-05 (§5.1.3; §5.1.4, printed p.23) [VC]', verified_at=now() where id='3183df38-6fe9-4ded-9c41-ba9f9304f44e' and verification_status not in ('verified_against_standard','corrected');

-- ---- M12003-03 (e2d58d06) Nutzungsmoeglichkeiten — 2 field(s) ----
-- bewaesserungsbeduerftigkeit_nachgewiesen
update public.fields set verification_status='verified_against_standard', verification_quote='Aufbereitetes Wasser als Bewässerungswasser kann, falls möglich und machbar, in folgenden Bereichen zur Anwendung kommen, sofern Bewässerungsbedürftigkeit bzw. -würdigkeit besteht: | Ableitung der Bewässerungsbedürftigkeit bzw. des Zusatzwasserbedarfs nach anerkanntem Verfahren, z. B. Merkblatt DWA-M 590 (ggf. Einbeziehung von Informationen des geologischen Dienstes oder der Landwirtschaftskammer); — printed p.13 / p.46', verification_note='md-verified 2026-09-05 (§3; Tab. 12 (§6), printed p.13 / p.46) [VC] — the "Ableitung … nach anerkanntem Verfahren" sentence sits in Tab. 12 (§6), not §4.2 as the clause tag says — STAGED S-1', verified_at=now() where id='caff03c8-4f53-4bca-be58-fb73a1925552' and verification_status not in ('verified_against_standard','corrected');
-- bewaesserungswuerdigkeit_bewertet
update public.fields set verification_status='verified_against_standard', verification_quote='Die Wirtschaftlichkeitsbetrachtung der Bewässerung ist im Hinblick auf die landwirtschaftliche und gartenbauliche Bewässerung im Rahmen einer Bewertung der Bewässerungswürdigkeit umzusetzen. Dies kann sowohl auf der Betriebsebene als auch auf höheren Ordnungsebenen, wie zum Beispiel im Rahmen von Bewässerungsverbänden sowie durch Wasserwirtschaftsplanungen, regional bzw. überregional, erfolgen. — printed p.14', verification_note='md-verified 2026-09-05 (§3, printed p.14) [VC]', verified_at=now() where id='4ffa2e88-a3a3-484f-b361-15e5f3e38edd' and verification_status not in ('verified_against_standard','corrected');

-- ---- M12003-04 (8da5fab1) Standort und Bodenmerkmale — 13 field(s) ----
-- bewaesserungstagebuch
update public.fields set verification_status='verified_against_standard', verification_quote='Die Bewässerung landwirtschaftlicher und gartenbaulicher Kulturen ist in einem Bewässerungstagebuch schlagbezogen zu dokumentieren (Tabelle 2). Bei der Bewässerung nicht landwirtschaftlicher Flächen ist eine betrieblich und inhaltlich geeignete Form der Dokumentation zu erstellen. | Tabelle 2: Beispiel für ein Bewässerungstagebuch in einem landwirtschaftlichen Betrieb | Start der Bewässerung & Ende der Bewässerung & Empfehlung Bewässerungsgabe (mm) | Wasserverbrauch total | Davon aufbereitetes Wasser ( $\mathrm{m}^{3}$ ) & Kommentar — printed p.17–18', verification_note='md-verified 2026-09-05 (§4.2 / Tab. 2, printed p.17–18) [VC] — hard only for landwirtschaftliche/gartenbauliche Kulturen; other areas need a "geeignete Form der Dokumentation"', verified_at=now() where id='75bad652-f613-48b9-97a8-33950f890f6b' and verification_status not in ('verified_against_standard','corrected');
-- bodenfeuchte_pct_nfk
update public.fields set verification_status='verified_against_standard', verification_quote='Die Einhaltung der guten fachlichen Praxis der Bewässerung bedeutet konkret, erst ab Unterschreiten einer bestimmten Bodenfeuchte (z. B. frühestens ab etwa $50 \%$ der nutzbaren Feldkapazität (nFK) bei landwirtschaftlichen Kulturen) die Bewässerung einzusetzen und die Wasserhaltekapazität des Bodens nicht vollständig (z. B. etwa nur $80 \%$ der $n F K$ bei landwirtschaftlichen Kulturen) durch eine Zusatzwassergabe aufzufüllen, wenn Niederschläge innerhalb der Folgetage möglich sind (nach LWK 2021). — printed p.17', verification_note='md-verified 2026-09-05 (§4.2, printed p.17) [VC] — 50 % / 80 % nFK are printed as "z. B." examples (nach LWK 2021), not limits — no gate; is_required=true on an example threshold — STAGED S-9', verified_at=now() where id='9d2ab955-6014-47a2-82a1-c97f977fd4f3' and verification_status not in ('verified_against_standard','corrected');
-- bewaesserungsverfahren
update public.fields set verification_status='verified_against_standard', verification_quote='Derzeit existieren in Deutschland folgende Bewässerungsverfahren/-methoden: | Beregnung: druckbedürftiges Verfahren, bei dem unter Einsatz von Düsen oder Sprinklern Bewässerungswasser wie Regen ausgebracht wird | Tropfbewässerung: druckbedürftiges Verfahren, bei dem Bewässerungswasser direkt auf oder in den Boden aufgebracht wird, zum Beispiel mithilfe von Tropfern oder anderen Emittern. | Hydroponische Systeme: Diese werden nur im Gartenbau verwendet | Drucklose Bewässerungverfahren, wie Einstau- oder Überstaubewässerung, werden in Deutschland derzeit nur noch im Ausnahmefall verwendet. Das gleiche gilt für die Rieselbewässerung. — printed p.15', verification_note='md-verified 2026-09-05 (§4.1, printed p.15) [VC] — token mikrosprueh = §4.1 "bodennahe Niederdruck-Sprinklersysteme … Mikrobewässerungssysteme" (md 475) + §5.4.4 Mikrosprühsysteme; furchenbewaesserung = Bild 4 title "Einstau-, Furchen- und Sprinklerbewässerung" (p.20)', verified_at=now() where id='e326087d-d225-4380-bc44-d501b1ead51b' and verification_status not in ('verified_against_standard','corrected');
-- zusatzwasserbedarf
update public.fields set verification_status='verified_against_standard', verification_quote='Die Planung des potenziellen Zusatzwasserbedarfs ist nach Merkblatt DWA-M 590:2019 oder anderen vergleichbaren Ansätzen auszurichten. Dabei sind auch die zu erwartenden üblichen annuellen und täglichen Zusatzwassermengen als Grundlage der Genehmigung zu ermitteln und im Risikomanagementplan (RMP) aufzunehmen. — printed p.17', verification_note='md-verified 2026-09-05 (§4.2, printed p.17) [VC] — the computation method is DWA-M 590 (NR here); this md only mandates the determination', verified_at=now() where id='65fd29b0-c7f4-4f6a-8f3d-8e55fbff2cb6' and verification_status not in ('verified_against_standard','corrected');
