-- bewaesserungswuerdigkeit_bewertet
update public.fields set verification_status='verified_against_standard', verification_quote='Die Wirtschaftlichkeitsbetrachtung der Bewässerung ist im Hinblick auf die landwirtschaftliche und gartenbauliche Bewässerung im Rahmen einer Bewertung der Bewässerungswürdigkeit umzusetzen. Dies kann sowohl auf der Betriebsebene als auch auf höheren Ordnungsebenen, wie zum Beispiel im Rahmen von Bewässerungsverbänden sowie durch Wasserwirtschaftsplanungen, regional bzw. überregional, erfolgen. — printed p.14', verification_note='md-verified 2026-09-05 (§3, printed p.14) [VC]', verified_at=now() where id='d40e8fed-fc62-412a-9cef-e1b6ea0dd266' and verification_status not in ('verified_against_standard','corrected');
-- zusatzwasserbedarfsverfahren
update public.fields set verification_status='verified_against_standard', verification_quote='Die Ermittlung des aktuellen Zusatzwasserbedarfs / der benötigten Zusatzwassergabe der bewässerten Kulturen zur Bewässerungssteuerung hat nach allgemein anerkannten Regeln, Verfahren und Methoden zu erfolgen, zum Beispiel nach Merkblatt DWA-M 591 (in Erstellung) oder anderen belastbaren und plausiblen Verfahren. | In einem Betriebsplan sind angewandte Regeln, Verfahren und Methoden der Ermittlung des Zusatzwasserbedarfs sowie der Bewässerungssteuerung aufzuführen. — printed p.17', verification_note='md-verified 2026-09-05 (§4.2, printed p.17) [VC]', verified_at=now() where id='89b6ec10-c843-426f-915e-4201d3554d82' and verification_status not in ('verified_against_standard','corrected');
-- sprinkler_typ
