-- ---- M12003-06 (cf221392) EU-Gueteklassen A/B/C/D Zuordnung — 7 field(s) ----
-- rmp_dokument
update public.fields set verification_status='verified_against_standard', verification_quote='Voraussetzung für eine sichere und nachhaltige Verwendung von aufbereitetem Wasser für die Bewässerung in Landwirtschaft, Gartenbau und Grünflächen ist ein proaktives Risikomanagement. In diesem Sinne sieht die Verordnung (EU) 2020/741 über Mindestanforderungen an die Wasserwiederverwendung (EU-WasserWVVO) in Artikel 5 die Erstellung eines Risikomanagementplans (RMP) vor. Wesentliche Elemente und Inhalte eines RMP werden in Anhang II der EU-WasserWVVO genannt. — printed p.45', verification_note='md-verified 2026-09-05 (§6; EU 2020/741 Art. 5, printed p.45) [VC]', verified_at=now() where id='805f2558-6bb4-42a8-b5b9-3552e3d5db4d' and verification_status not in ('verified_against_standard','corrected');
