update public.fields set verification_status='verified_against_standard', verification_quote='Weitere wichtige Informationen, die gemeinsam mit den anderen Akteuren abgestimmt werden sollten, sind Maßnahmen und Vorkehrungen, die bei Störfällen und Auffälligkeiten zu ergreifen sind. Hier sind insbesondere der Informationsfluss und die Kommunikationswege mit dem Betreiber der Aufbereitungsanlage klar festzulegen. Auch diese Informationen müssen bei der Erstellung des RMP beigebracht werden. — printed p.45–46', verification_note='md-verified 2026-09-05 (§6, printed p.45–46) [VC]', verified_at=now() where id='534f6997-450a-4544-984d-4ce3567be56a' and verification_status not in ('verified_against_standard','corrected');
