update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 12: Beschreibung der Systembestandteile für Verteilung, Speicherung und Aufbringung (Hinweis zur Nutzung: Die Listung ist nicht erschließend. Es können sowohl zusätzliche Aspekte notwendig werden oder hier aufgeführte gegebenenfalls nicht nötig sein. Das ist zu prüfen.) | Benennung und Charakterisierung der zu bewässernden Kulturen oder zu bewässernden Grünflächen; | Verwertungswege der zu bewässernden Pflanzen (z. B. Kartoffeln: Speise- oder Stärkekartoffeln; Mais: Biogas oder Futtermittel); — printed p.46', verification_note='md-verified 2026-09-05 (Tab. 12 (§6), printed p.46) [VC] — text field with two suggested values seeded 2026-08-01 from the "z. B." examples — consistent with "Die Listung ist nicht erschließend"', verified_at=now() where id='8048c039-8877-41e9-b526-14647ef70bc7' and verification_status not in ('verified_against_standard','corrected');
-- betriebsplan_dokument
update public.fields set verification_status='verified_against_standard', verification_quote='In einem Betriebsplan sind angewandte Regeln, Verfahren und Methoden der Ermittlung des Zusatzwasserbedarfs sowie der Bewässerungssteuerung aufzuführen. | Im Betriebsplan ist festlegen, wie und wie oft die Überprüfung der Sicherheitseinrichtungen bei hybrider Wasserherkunft zu erfolgen hat. | Reinigungs- und Desinfektionshäufigkeit von Speichern (Anlagenbehandlung) sind sowohl im RMP als auch in einem Betriebsplan aufzuführen. — printed p.17 / p.24 / p.48', verification_note='md-verified 2026-09-05 (§4.2; §5.1.5; §7.1, printed p.17 / p.24 / p.48) [VC] — md 749 prints "ist festlegen" (as in the draft)', verified_at=now() where id='94446cee-a932-4581-8751-421999d88def' and verification_status not in ('verified_against_standard','corrected');
-- attest_m12003_06_cr_10
update public.fields set verification_status='verified_against_standard', verification_quote='Voraussetzung für eine sichere und nachhaltige Verwendung von aufbereitetem Wasser für die Bewässerung in Landwirtschaft, Gartenbau und Grünflächen ist ein proaktives Risikomanagement. In diesem Sinne sieht die Verordnung (EU) 2020/741 über Mindestanforderungen an die Wasserwiederverwendung (EU-WasserWVVO) in Artikel 5 die Erstellung eines Risikomanagementplans (RMP) vor. — printed p.45', verification_note='md-verified 2026-09-05 (§6; EU 2020/741 Art. 5, printed p.45) [VC] — attestation flag for gate CR-10; the obligation is printed (EU Art. 5); clause_reference NULL — STAGED S-1', verified_at=now() where id='b2d2ea2e-54fb-4e02-ba56-043fb7377a19' and verification_status not in ('verified_against_standard','corrected');

