update public.fields set verification_status='verified_against_standard', verification_quote='Derzeit können für die Desinfektion von Bewässerungswasser keine technischen Richtwerte angegeben werden. Es ist daher eine anwendungsbezogene Einzelfallprüfung vorzunehmen. Eine Ausnahme stellt hier Güteklasse A aufgrund der hohen Qualität dar. Im Falle der Chlorung kann auf Vorgaben nach ISO 16075-2:2020 zurückgegriffen werden $(0,2 \mathrm{mg} / \mathrm{l}$ bis $1 \mathrm{mg} / \mathrm{l}$ Restchlor nach 30 min Kontaktzeit). — printed p.50', verification_note='md-verified 2026-09-05 (§7.2.3; ISO 16075-2:2020, printed p.50) [VC] — 0,2–1 mg/l is a printed RANGE (SR-2) for class A chlorination only ("kann"); no gate — STAGED S-8 (warn)', verified_at=now() where id='dd81015a-caa8-4257-b292-d07d597942a2' and verification_status not in ('verified_against_standard','corrected');
