-- bewaesserungsverfahren
update public.fields set verification_status='verified_against_standard', verification_quote='Derzeit existieren in Deutschland folgende Bewässerungsverfahren/-methoden: | Beregnung: druckbedürftiges Verfahren, bei dem unter Einsatz von Düsen oder Sprinklern Bewässerungswasser wie Regen ausgebracht wird | Tropfbewässerung: druckbedürftiges Verfahren, bei dem Bewässerungswasser direkt auf oder in den Boden aufgebracht wird, zum Beispiel mithilfe von Tropfern oder anderen Emittern. | Hydroponische Systeme: Diese werden nur im Gartenbau verwendet | Drucklose Bewässerungverfahren, wie Einstau- oder Überstaubewässerung, werden in Deutschland derzeit nur noch im Ausnahmefall verwendet. Das gleiche gilt für die Rieselbewässerung. — printed p.15', verification_note='md-verified 2026-09-05 (§4.1, printed p.15) [VC] — token mikrosprueh = §4.1 "bodennahe Niederdruck-Sprinklersysteme … Mikrobewässerungssysteme" (md 475) + §5.4.4 Mikrosprühsysteme; furchenbewaesserung = Bild 4 title "Einstau-, Furchen- und Sprinklerbewässerung" (p.20)', verified_at=now() where id='e9a1b41f-af0f-4d10-82b0-3fd101f8cd90' and verification_status not in ('verified_against_standard','corrected');
