update public.fields set verification_status='verified_against_standard', verification_quote='1) Bei Aerosolbildung bei der Sprinklerbewässerung werden nach EU-Leitlinien 2022/C 298/01 für Legionella spp. $<1000 \mathrm{KBE} / \mathrm{l}$ erforderlich. (KBE Koloniebildende Einheiten) | Bild 4: Beispiele für die Zuordnung von Güteklassen nach EU-WasserWVVO zu den angebauten Kulturen bei Einstau-, Furchen- und Sprinklerbewässerung — printed p.20', verification_note='md-verified 2026-09-05 (Bild 4 Anm. 1) (§4.3), printed p.20) [VC] — the < 1000 KBE/l value originates in EU-Leitlinien 2022/C 298/01 and is printed here as a figure note; no gate encodes it — STAGED S-8', verified_at=now() where id='efa00c22-5e10-448b-8311-2796311b7029' and verification_status not in ('verified_against_standard','corrected');
-- e_coli_konz
update public.fields set verification_status='verified_against_standard', verification_quote='Dies können die Indikatororganismen sein, die im Regelmonitoring betrachtet werden (z. B. E. coli, intestinale Enterokokken sowie ggf. Legionellen), sowie gegebenenfalls andere für den Menschen relevante Krankheitserreger (z. B. coliforme Bakterien, Pseudomonas aeruginosa) im Falle der Güteklasse A. — printed p.48–49', verification_note='md-verified 2026-09-05 (§7.2.1, printed p.48–49) [VC] — parameter is printed; the class limits are EU 2020/741 Anhang I (NR in this md) — no gate possible from this source', verified_at=now() where id='42056239-2fb4-46fd-82bd-8a8aac3f7086' and verification_status not in ('verified_against_standard','corrected');
-- helminthen_eier
update public.fields set verification_status='verified_against_standard', verification_quote='3) Bei einer Bewässerung von Weideflächen oder Futterpflanzen ist nachzuweisen, dass intestinale Nematoden (Eier von Helminthen) mit $\leqslant 1$ Ei je Liter im Bewässerungswasser vorhanden sind. | Bild 4: Beispiele für die Zuordnung von Güteklassen nach EU-WasserWVVO zu den angebauten Kulturen bei Einstau-, Furchen- und Sprinklerbewässerung — printed p.20', verification_note='md-verified 2026-09-05 (Bild 4/5 Anm. 3) (§4.3), printed p.20) [VC] — "ist nachzuweisen … ≤ 1 Ei je Liter" is a printed hard limit (Weide-/Futterpflanzen) with no gate — STAGED S-8', verified_at=now() where id='33004081-d3c2-496c-bfdb-2f1d88fa0553' and verification_status not in ('verified_against_standard','corrected');

