update public.fields set verification_status='verified_against_standard', verification_quote='Bei simultaner Einspeisung aus verschiedenen Quellen sind geeignete Sicherungseinrichtungen (Rückflussverhinderer, Systemtrenner, freier Auslauf) zu verwenden. Insbesondere bei Verbindungen zum Trinkwassernetz sind hier Anforderungen aus DIN EN 1717 und/oder DIN EN 13959:2005, DIN EN 12729:2023 etc. zu beachten. — printed p.24', verification_note='md-verified 2026-09-05 (§5.1.5, printed p.24) [VC] — applies to hybride Wasserherkunft only; CR-08 is unconditional — STAGED S-6', verified_at=now() where id='e7e4deb7-7ed5-4d25-a44c-1a5cc015c7e3' and verification_status not in ('verified_against_standard','corrected');
-- kennzeichnung_farbe
update public.fields set verification_status='verified_against_standard', verification_quote='Hierbei erfolgt eine Farbgebung der technischen Bauteile, wie Rohre, Emitter etc., in den Farben „Pantone Purple 522C“, „Pantone Purple 512C" oder vergleichbaren Farben. Dies muss als Abgrenzung zur Farbgebung von Trinkwasserverteilungssystemen und Abwasserleitungen erfolgen. | Nach DVGW/KTW gekennzeichnete Wasserleitungen (Farbe Blau, z. B. RAL 5005) dürfen für den Transport und die Verteilung von aufbereitetem Wasser nicht verwendet werden. — printed p.23–24', verification_note='md-verified 2026-09-05 (§5.1.4; Tab. 4, printed p.23–24) [VC] — "Es wird empfohlen, exponierte technische Elemente … entsprechend diesem internationalen Standard auszurüsten" (md 708) — is_required=true on a recommendation — STAGED S-9', verified_at=now() where id='5f53bb41-2783-4c1a-9ccd-7f6eb8380885' and verification_status not in ('verified_against_standard','corrected');
-- markierung_oberflaeche_anteil
update public.fields set verification_status='verified_against_standard', verification_quote='Bei einer Nutzung bestehender Verteilungs- und Bewässerungssysteme müssen technische Bauteile, soweit wie möglich und technisch realisierbar, gekennzeichnet werden. Auf die Nutzung von aufbereitetem Wasser ist auch hier hinzuweisen. Eine nachträgliche Farbmarkierung muss dabei mindestens $60 \%$ der Oberfläche umfassen. — printed p.23', verification_note='md-verified 2026-09-05 (§5.1.4, printed p.23) [VC] — applies to nachträgliche Farbmarkierung of existing systems only; CR-07 applies it unconditionally — STAGED S-6', verified_at=now() where id='1b22289e-e9bc-411b-a2b7-83af614e608b' and verification_status not in ('verified_against_standard','corrected');
-- freier_auslauf
update public.fields set verification_status='verified_against_standard', verification_quote='Bei simultaner Einspeisung aus verschiedenen Quellen sind geeignete Sicherungseinrichtungen (Rückflussverhinderer, Systemtrenner, freier Auslauf) zu verwenden. Insbesondere bei Verbindungen zum Trinkwassernetz sind hier Anforderungen aus DIN EN 1717 und/oder DIN EN 13959:2005, DIN EN 12729:2023 etc. zu beachten. — printed p.24', verification_note='md-verified 2026-09-05 (§5.1.5, printed p.24) [VC] — applies to hybride Wasserherkunft only — STAGED S-6', verified_at=now() where id='47936dea-7f69-4690-b50e-5841187ac5e1' and verification_status not in ('verified_against_standard','corrected');
-- systemtrenner_vorhanden
