-- ---- M12003-13 (12dd0e76) Abstandsregelungen und Pufferdistanzen — 5 field(s) ----
-- abstand_oberflaechengewaesser_eingehalten
update public.fields set verification_status='verified_against_standard', verification_quote='Im RMP ist festzulegen, welche Abstände der bewässernden Fläche(n) zu Oberflächengewässern im konkreten Fall einzuhalten sind. Empfohlen werden grundsätzlich Maximalabstände analog zur Abstandsregelung zu Oberflächengewässern bei der Anwendung von Pflanzenschutzmitteln § 4a PflSchAnwV) sowie Mindestabstände nach § 5 Absatz 2 und Absatz 3 DüV. | Bei der Chlorung sowie Wasserstoffperoxid- und PES-Behandlung ist bei der Bewässerung mit dem so behandelten Wasser jeweils ein Sicherheitsabstand zu Oberflächengewässern einzuhalten, um zu vermeiden, dass die Desinfektionsmittel in das Gewässer gelangen. — printed p.31 / p.50–51', verification_note='md-verified 2026-09-05 (§5.2.4.3; §7.2.3, printed p.31 / p.50–51) [VC] — md 964 prints "Pflanzenschutzmitteln § 4a PflSchAnwV)" without the opening parenthesis (transcription); CR-14 only checks this when disinfecting — STAGED S-5', verified_at=now() where id='54804750-4354-4955-935d-23aab3c85b99' and verification_status not in ('verified_against_standard','corrected');
-- abstand_zu_sensitiv
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Bewässerung mit aufbereitetem Wasser sind gegebenenfalls Abstände zu sensiblen Bereichen einzuhalten, wie zum Beispiel zu | bewohnten Gebieten, | Straßen und Wegen, | Oberflächengewässern, | Sportstätten. | Je nach Anwendungsbereich, Wasserqualität und Örtlichkeit der Anwendung sind dabei unterschiedlich große Abstände zu sensiblen Bereichen einzuhalten. — printed p.23', verification_note='md-verified 2026-09-05 (§5.1.3; Tab. 7/8/9, printed p.23) [VC] — "gegebenenfalls" — is_required=true — STAGED S-9', verified_at=now() where id='ab50c701-6b12-4852-8122-6008f910c687' and verification_status not in ('verified_against_standard','corrected');
-- steuerbarer_zugang
update public.fields set verification_status='verified_against_standard', verification_quote='Eine Abstandsregelung zu Wegen etc. entfällt, wenn durch Zugangssteuerung die Passage von Menschen während der Bewässerung unterbleibt (steuerbarer Zugang). | Folgende Empfehlungen gelten unter der Voraussetzung, dass Passanten sich während des Bewässerungsvorgangs an der Bewässerungsanlage entlang bewegen könnten (nicht steuerbarer Zugang) (siehe Tabelle 9). — printed p.33', verification_note='md-verified 2026-09-05 (§5.4.4, printed p.33) [VC]', verified_at=now() where id='8ce75572-8c5a-42b6-bad7-af02dafaecc1' and verification_status not in ('verified_against_standard','corrected');
-- min_abstand
update public.fields set verification_status='verified_against_standard', verification_quote='Beispiel: Eine Regnerkanone hat unter normalen Betriebsbedingungen ohne Windeinflüsse eine Wurfweite von 25 m . Es wird mit Wasser der Güteklasse D bewässert. Es ist zudem kein Spritzschutz vor dem Wohngebiet vorhanden. Gemäß Tabelle 7 beträgt der erforderliche Abstand zwischen Regner und dem bebauten Wohngebiet mindestens 50 m (2-fache Wurfweite). — printed p.29–30', verification_note='md-verified 2026-09-05 (§5.2.4.2 example; Tab. 7, printed p.29–30) [VC] — derived (Gl-Helper-5); the printed worked example is 25 m × 2 = 50 m', verified_at=now() where id='bab92106-baba-433a-8363-46686da83638' and verification_status not in ('verified_against_standard','corrected');
-- faktor
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 7: Empfohlene Abstandsregelung für Trommelregner mit Regnerkanone, Endkanone bei Kreis- und Linearbewässerungsmaschinen sowie sonstige druckbetriebene Sprinklersysteme mit Wurfweiten > 2 m | Güteklasse & Mindestabstand ohne Spritzschutz & Mindestabstand mit Spritzschutz | A bis C & 1-fache Wurfweite | D & 2-fache Wurfweite | Tabelle 8: Empfohlene Abstandsregelung für Kreis- und Linearbewässerungsmaschinen ohne Endkanone, Düsenwagen bei Trommelregnern sowie sonstige Sprinklersysteme mit $\leqslant 2 \mathrm{~m}$ Wurfweite | D & 3-fache Wurfweite — printed p.30 / p.33', verification_note='md-verified 2026-09-05 (Tab. 7 / Tab. 8 / Tab. 9, printed p.30 / p.33) [VC] — faktor ∈ {1, 2, 3} is fully determined by gueteklasse × table (Tab. 7/9 vs Tab. 8) × spritzschutz — a standard_fixed lookup that is hand-enterable (#22 class) — STAGED S-4', verified_at=now() where id='b448a4c3-132f-4f09-999e-17694d1c6dc9' and verification_status not in ('verified_against_standard','corrected');

-- ---- M12003-14 (70caffba) Aerosolrisiko und Spritzschutz — 3 field(s) ----
-- spritzschutz_staerke_m
update public.fields set verification_status='verified_against_standard', verification_quote='Es wird empfohlen, Spitzschutzhecken einer ortsüblichen Artenzusammensetzung mit mindestens 2 m Höhe sowie mindestens 1 m Stärke zu etablieren. Bis zum Erreichen dieser Situation hat die sich etablierende Hecke noch keinen ausreichenden Spritzschutz. — printed p.30–31', verification_note='md-verified 2026-09-05 (§5.2.4.2, printed p.30–31) [VC] — md prints "Spitzschutzhecken" (as in the draft); "Es wird empfohlen" — no gate — STAGED S-8', verified_at=now() where id='aadf517b-70ee-4d9c-bcb3-c0e86562fbf9' and verification_status not in ('verified_against_standard','corrected');
-- spritzschutz_vorhanden
update public.fields set verification_status='verified_against_standard', verification_quote='Der Einsatz von Spritzschutzhecken und ähnlichen Lösungen kann dabei auch als funktionale Barriere wirken und dabei erforderliche Abstände reduzieren oder ersetzen. | Es wird empfohlen, Spitzschutzhecken einer ortsüblichen Artenzusammensetzung mit mindestens 2 m Höhe sowie mindestens 1 m Stärke zu etablieren. | Die Mindesthöhe von Spritzschutzhecken oder künstlichen Wänden im urbanen Bereich ist die Höhe des Wasserstrahls. — printed p.23 / p.30–31 / p.33', verification_note='md-verified 2026-09-05 (§5.1.3; §5.2.4.2; §5.4.4, printed p.23 / p.30–31 / p.33) [VC] — clause tag "§5.1.3 / Tab. 7,8,9" lacks §5.2.4.2 where the 2 m / 1 m sentence sits — STAGED S-1', verified_at=now() where id='c78b1ed3-f6a1-489f-8b73-4c9ac9a94a4a' and verification_status not in ('verified_against_standard','corrected');
