update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Frostschutzberegnung werden in der Regel innerhalb weniger Stunden große Wassermengen ausgebracht, bis zu 50 mm pro Frostnacht. Es fällt daher ein Wasserbedarf pro Nacht von bis zu $500 \mathrm{~m}^{3}$ je Hektar an. — printed p.44', verification_note='md-verified 2026-09-05 (§5.6.5, printed p.44) [VC] — "in der Regel … bis zu 50 mm" is a typical magnitude, not a limit — engineer_input', verified_at=now() where id='e60b3f72-77f5-4a97-8234-32664dec935e' and verification_status not in ('verified_against_standard','corrected');
