update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Frostschutzberegnung werden in der Regel innerhalb weniger Stunden große Wassermengen ausgebracht, bis zu 50 mm pro Frostnacht. Es fällt daher ein Wasserbedarf pro Nacht von bis zu $500 \mathrm{~m}^{3}$ je Hektar an. — printed p.44', verification_note='md-verified 2026-09-05 (§5.6.5, printed p.44) [VC] — derived (Gl-Helper-4); 50 mm × 1 ha ≙ 500 m³ is the printed worked figure', verified_at=now() where id='cb9c23a8-c3ee-4eab-bc19-738cbd922a94' and verification_status not in ('verified_against_standard','corrected');

