-- bewaesserungstagebuch
update public.fields set verification_status='verified_against_standard', verification_quote='Die Bewässerung landwirtschaftlicher und gartenbaulicher Kulturen ist in einem Bewässerungstagebuch schlagbezogen zu dokumentieren (Tabelle 2). Bei der Bewässerung nicht landwirtschaftlicher Flächen ist eine betrieblich und inhaltlich geeignete Form der Dokumentation zu erstellen. | Tabelle 2: Beispiel für ein Bewässerungstagebuch in einem landwirtschaftlichen Betrieb | Start der Bewässerung & Ende der Bewässerung & Empfehlung Bewässerungsgabe (mm) | Wasserverbrauch total | Davon aufbereitetes Wasser ( $\mathrm{m}^{3}$ ) & Kommentar — printed p.17–18', verification_note='md-verified 2026-09-05 (§4.2 / Tab. 2, printed p.17–18) [VC] — hard only for landwirtschaftliche/gartenbauliche Kulturen; other areas need a "geeignete Form der Dokumentation"', verified_at=now() where id='5402554d-9c4e-4da5-ae5c-73412dd570ef' and verification_status not in ('verified_against_standard','corrected');
