-- ---- M12003-19 (69b8617d) Risikomanagementplan — 4 field(s) ----
-- betriebsplan_dokument
update public.fields set verification_status='verified_against_standard', verification_quote='In einem Betriebsplan sind angewandte Regeln, Verfahren und Methoden der Ermittlung des Zusatzwasserbedarfs sowie der Bewässerungssteuerung aufzuführen. | Im Betriebsplan ist festlegen, wie und wie oft die Überprüfung der Sicherheitseinrichtungen bei hybrider Wasserherkunft zu erfolgen hat. | Reinigungs- und Desinfektionshäufigkeit von Speichern (Anlagenbehandlung) sind sowohl im RMP als auch in einem Betriebsplan aufzuführen. — printed p.17 / p.24 / p.48', verification_note='md-verified 2026-09-05 (§4.2; §5.1.5; §7.1, printed p.17 / p.24 / p.48) [VC] — md 749 prints "ist festlegen" (as in the draft)', verified_at=now() where id='b049690c-436b-4e7d-8435-c58710444068' and verification_status not in ('verified_against_standard','corrected');
-- attest_m12003_19_cr_10
update public.fields set verification_status='verified_against_standard', verification_quote='Voraussetzung für eine sichere und nachhaltige Verwendung von aufbereitetem Wasser für die Bewässerung in Landwirtschaft, Gartenbau und Grünflächen ist ein proaktives Risikomanagement. In diesem Sinne sieht die Verordnung (EU) 2020/741 über Mindestanforderungen an die Wasserwiederverwendung (EU-WasserWVVO) in Artikel 5 die Erstellung eines Risikomanagementplans (RMP) vor. — printed p.45', verification_note='md-verified 2026-09-05 (§6; EU 2020/741 Art. 5, printed p.45) [VC] — attestation flag for gate CR-10 (ws 19 twin of ws 06); clause_reference NULL — STAGED S-1', verified_at=now() where id='7228c415-cfad-410a-80dc-d32ef8a1163f' and verification_status not in ('verified_against_standard','corrected');
-- storfall_plan
update public.fields set verification_status='verified_against_standard', verification_quote='Weitere wichtige Informationen, die gemeinsam mit den anderen Akteuren abgestimmt werden sollten, sind Maßnahmen und Vorkehrungen, die bei Störfällen und Auffälligkeiten zu ergreifen sind. Hier sind insbesondere der Informationsfluss und die Kommunikationswege mit dem Betreiber der Aufbereitungsanlage klar festzulegen. Auch diese Informationen müssen bei der Erstellung des RMP beigebracht werden. — printed p.45–46', verification_note='md-verified 2026-09-05 (§6, printed p.45–46) [VC]', verified_at=now() where id='b2775ca4-4776-46f0-ab72-2fedf115e94f' and verification_status not in ('verified_against_standard','corrected');
-- rmp_dokument
update public.fields set verification_status='verified_against_standard', verification_quote='Voraussetzung für eine sichere und nachhaltige Verwendung von aufbereitetem Wasser für die Bewässerung in Landwirtschaft, Gartenbau und Grünflächen ist ein proaktives Risikomanagement. In diesem Sinne sieht die Verordnung (EU) 2020/741 über Mindestanforderungen an die Wasserwiederverwendung (EU-WasserWVVO) in Artikel 5 die Erstellung eines Risikomanagementplans (RMP) vor. Wesentliche Elemente und Inhalte eines RMP werden in Anhang II der EU-WasserWVVO genannt. — printed p.45', verification_note='md-verified 2026-09-05 (§6; EU 2020/741 Art. 5, printed p.45) [VC]', verified_at=now() where id='70946b89-4329-43f4-b56a-3deb81468799' and verification_status not in ('verified_against_standard','corrected');

