-- desinfektion_methode
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 13: Mögliche und zulässige Maßnahmen zur Desinfektion von aufbereitetem Wasser aus und in Speichersystemen in Anlehnung an ISO 16075-3:2021 | Chlorung | Ozonung | Peressigsäure (PES-)Behandlung | Ultrafiltration | UV-Bestrahlung | Wasserstoffperoxid ( $\mathrm{H}_{2} \mathrm{O}_{2}$ ) Behandlung | Eine chemische Behandlung des aufbereiteten Wassers mit anderen als in Tabelle 14 genannten Mitteln wird nicht empfohlen. — printed p.49–50', verification_note='md-verified 2026-09-05 (§7.2.3 / Tab. 13, printed p.49–50) [VC] — six tokens = the six Tab. 13 rows; token thermisch is §7.2.5 Anlagendesinfektion (plant, not water) — mixed concept, STAGED S-1; Tab. 13 restricts open storage to "mit Start der Bewässerung"/"Befüllen von Transportbehältern" (no timing field → not encodable)', verified_at=now() where id='f2c5e5d4-2b55-4a6e-837e-5efca9a193dd' and verification_status not in ('verified_against_standard','corrected');
-- restchlor_konz
update public.fields set verification_status='verified_against_standard', verification_quote='Derzeit können für die Desinfektion von Bewässerungswasser keine technischen Richtwerte angegeben werden. Es ist daher eine anwendungsbezogene Einzelfallprüfung vorzunehmen. Eine Ausnahme stellt hier Güteklasse A aufgrund der hohen Qualität dar. Im Falle der Chlorung kann auf Vorgaben nach ISO 16075-2:2020 zurückgegriffen werden $(0,2 \mathrm{mg} / \mathrm{l}$ bis $1 \mathrm{mg} / \mathrm{l}$ Restchlor nach 30 min Kontaktzeit). — printed p.50', verification_note='md-verified 2026-09-05 (§7.2.3; ISO 16075-2:2020, printed p.50) [VC] — 0,2–1 mg/l is a printed RANGE (SR-2) for class A chlorination only ("kann"); no gate — STAGED S-8 (warn)', verified_at=now() where id='bc57f852-7ab2-4579-989b-1f333f0d2366' and verification_status not in ('verified_against_standard','corrected');
