update public.fields set verification_status='verified_against_standard', verification_quote='Das Betriebspersonal ist entsprechend zu schulen. Das Risikomanagement muss entsprechend der verwendeten Güteklasse gestaltet werden (siehe Abschnitt 6). | Betriebspersonal ist zu schulen. | Das schließt die Information, Aufklärung und gegebenenfalls Schulung des Betriebspersonals ein. — printed p.44 / p.37 / p.35', verification_note='md-verified 2026-09-05 (§5.6.5; §5.5.5; §5.4.5, printed p.44 / p.37 / p.35) [VC] — hard only for Frostschutzberegnung (§5.6.5) and sonstige Anwendungen (§5.5.5); "gegebenenfalls" on Betriebsgelände — is_required=true globally over-generalises — STAGED S-9', verified_at=now() where id='0dd0605f-77c8-42d4-a3ea-1d90eb73ab4f' and verification_status not in ('verified_against_standard','corrected');
-- expositionspfade_dokumentiert
update public.fields set verification_status='verified_against_standard', verification_quote='Für den Menschen, und damit auch für die umsetzenden Betriebe, sind bei der Wiederverwendung von aufbereitetem Wasser für die Bewässerung in Landwirtschaft, Gartenbau, Grünanlagen sowie im GaLaBau folgende Expositionspfade zu berücksichtigen (Achtung: Exposition ist nicht gleichzusetzen mit real existenten Risiken): | direkte Aufnahme über Inhalation von Aerosolen | direkte Aufnahme über Ingestion von Tropfen | direkte Aufnahme über dermalen Kontakt | können im RMP für die einzelnen Bewässerungsflächen die je- weils relevanten Expositionspfade tabellarisch aufgelistet werden. — printed p.57–58', verification_note='md-verified 2026-09-05 (§8 / Tab. 15, printed p.57–58) [VC] — CR-13 (ws 08) meant to check this has no condition — STAGED S-2', verified_at=now() where id='0952c944-7456-482e-97ca-57d2dc6704fa' and verification_status not in ('verified_against_standard','corrected');

