-- M12003-05 Gl-Helper-1: speichervolumen = bewaesserungshoehe * flaeche_groesse * 10
update public.equations set verification_status='verified_against_standard', verification_quote='Tabelle 5: Beispiel für eine Dimensionierung eines ortsfesten Speichers | Zu bewässernde Fläche & 10 ha | Normgröße Bewässerungshöhe & 20 mm | Gesamtbedarf Bewässerungswasser & $2000 \mathrm{~m}^{3}$ | Minimal erforderliches Speichervolumen | $2000 \mathrm{~m}^{3}$ — printed p.26', verification_note='md-verified 2026-09-05 (§5.2.1 / Tab. 5 worked example, printed p.26) [VC] — no printed formula — the worked example (10 ha × 20 mm → 2000 m³) fixes the relation; the ×10 is the mm·ha→m³ unit conversion, arithmetic not a printed coefficient', verified_at=now() where id='aea87475-a0d6-4b07-938e-4fcbe6eeb15c' and verification_status <> 'verified_against_standard';
-- M12003-05 Gl-Helper-2: dauer_durchgang_h = speichervolumen / pumpenleistung
update public.equations set verification_status='verified_against_standard', verification_quote='Tabelle 5: Beispiel für eine Dimensionierung eines ortsfesten Speichers | Minimal erforderliches Speichervolumen | $2000 \mathrm{~m}^{3}$ | Installierte Pumpenleistung für die Bewässerung & $50 \mathrm{~m}^{3} / \mathrm{h}$ | Dauer eines Bewässerungsdurchgangs | 40 h | entspricht & $1,7 \mathrm{~d}$ — printed p.26', verification_note='md-verified 2026-09-05 (§5.2.1 / Tab. 5 worked example, printed p.26) [VC] — no printed formula — worked example 2000 m³ / 50 m³/h = 40 h', verified_at=now() where id='aec0e88e-8cdd-483b-98ae-601aae5257d2' and verification_status <> 'verified_against_standard';
-- M12003-05 Gl-Helper-3: dauer_befuellung_h = speichervolumen / zulauf_volumenstrom
update public.equations set verification_status='verified_against_standard', verification_quote='Tabelle 5: Beispiel für eine Dimensionierung eines ortsfesten Speichers | Minimal erforderliches Speichervolumen | $2000 \mathrm{~m}^{3}$ | Zulauf aus der Aufbereitung & $20 \mathrm{~m}^{3} / \mathrm{h}$ | Dauer einer Befüllung | 100 h | entspricht & $4,2 \mathrm{~d}$ | In diesem Beispiel ist eine Bewässerung spätestens alle 4 Tage mit 20 mm möglich. — printed p.26', verification_note='md-verified 2026-09-05 (§5.2.1 / Tab. 5 worked example, printed p.26) [VC] — no printed formula — worked example 2000 m³ / 20 m³/h = 100 h = 4,2 d', verified_at=now() where id='6648bd89-9395-4904-b765-82f77808b7c5' and verification_status <> 'verified_against_standard';
-- M12003-05 Gl-Helper-4: frostschutz_volumen = frostschutz_menge * flaeche_groesse * 10
update public.equations set verification_status='verified_against_standard', verification_quote='Bei der Frostschutzberegnung werden in der Regel innerhalb weniger Stunden große Wassermengen ausgebracht, bis zu 50 mm pro Frostnacht. Es fällt daher ein Wasserbedarf pro Nacht von bis zu $500 \mathrm{~m}^{3}$ je Hektar an. — printed p.44', verification_note='md-verified 2026-09-05 (§5.6.5, printed p.44) [VC] — no printed formula — the printed pair 50 mm ↔ 500 m³/ha fixes the relation (×10 = mm·ha→m³)', verified_at=now() where id='e2f4b9d1-a670-4785-b3ee-7e4299353d9f' and verification_status <> 'verified_against_standard';
-- M12003-05 Gl-Helper-5: min_abstand = faktor * wurfweite
update public.equations set verification_status='verified_against_standard', verification_quote='Beispiel: Eine Regnerkanone hat unter normalen Betriebsbedingungen ohne Windeinflüsse eine Wurfweite von 25 m . Es wird mit Wasser der Güteklasse D bewässert. Es ist zudem kein Spritzschutz vor dem Wohngebiet vorhanden. Gemäß Tabelle 7 beträgt der erforderliche Abstand zwischen Regner und dem bebauten Wohngebiet mindestens 50 m (2-fache Wurfweite). | A bis C & 1-fache Wurfweite | D & 2-fache Wurfweite | D & 3-fache Wurfweite — printed p.29–30 / p.33', verification_note='md-verified 2026-09-05 (§5.2.4.2 / Tab. 7 (Tab. 8, Tab. 9), printed p.29–30 / p.33) [VC] — no printed formula — Tab. 7/8/9 print the multiplier (1-/2-/3-fache Wurfweite) and the §5.2.4.2 example (25 m × 2 = 50 m); input faktor must be the table lookup (STAGED S-4)', verified_at=now() where id='4c1690d7-aa5b-461b-ab2e-45d32b7190ea' and verification_status <> 'verified_against_standard';
